{
  "headline": "FDA's records trace our supply to a plant classified OAI 250 days before the posting",
  "headline_cites": ["D27"],
  "sentences": [
    {
      "text": "FDA first posted the lidocaine hydrochloride shortage on 2012-02-22 and it remains Current as of 2026-10-21.",
      "cites": ["E81", "E71"]
    },
    {
      "text": "Multiple manufacturers are listed on the FDA shortage list including Hikma Pharmaceuticals USA Inc., Fresenius Kabi USA LLC, and Hospira Inc.",
      "cites": ["E77", "E76", "E78"]
    },
    {
      "text": "Our Corvale East, General, and Lakeside sites use Hikma 20 mg/mL 50 mL vials (NDC 0143-9575-10) manufactured by Hikma Farmacêutica Portugal.",
      "cites": ["E1", "E8", "E13", "E19"]
    },
    {
      "text": "Our sites also use Fresenius Kabi 10 mg/mL 10 mL vials (NDC 63323-482-17) from Fresenius Kabi Austria and Fresenius Kabi USA LLC plants.",
      "cites": ["E5", "E17", "E28", "E37", "E51"]
    },
    {
      "text": "FDA inspected the Fresenius Kabi Austria plant (FEI 3003708554) most recently on 2024-03-21 and classified it VAI.",
      "cites": ["E27", "E28"]
    },
    {
      "text": "FDA inspected the Fresenius Kabi USA LLC plant (FEI 3001833549) on 2023-10-13 and classified it VAI.",
      "cites": ["E49", "E51"]
    },
    {
      "text": "FDA inspected the Hospira Inc. plant (FEI 1021343) on 2025-02-07 and classified it NAI.",
      "cites": ["E66"]
    },
    {
      "text": "FDA inspection 732886 at Hospira Inc. ended 2011-06-17 classified OAI, 250 days before the shortage posting on 2012-02-22.",
      "cites": ["D27", "E58"]
    },
    {
      "text": "Corvale East holds 357 vials of 20 mg/mL 50 mL (18.9 days on hand) and can transfer 40 vials to Corvale Lakeside which holds 15 vials (3.9 days on hand), raising Lakeside to 14 days.",
      "cites": ["D1", "D3", "D39"]
    }
  ]
}
